B.Om=new A.cM("Barista",B.Yy)
B.Yp=s(["Hey\u2014stay with me. Can you hear me?","Who are you?"],t.s)
B.NJ=new A.ct("Try to remember","intro_cannot_remember_name",!0,!1)
B.WR=s([B.NJ],t.u)
